import * as fs from "fs";
import * as os from "os";
import * as path from "path";

jest.mock("graceful-fs", () => {
  throw new Error("graceful-fs is not available");
});

function locateJsonfileModule(): string {
  const bases = [__dirname, process.cwd()];
  const layouts = [
    path.join("subject_repositories", "node-jsonfile", "index.js"),
    path.join("node-jsonfile", "index.js"),
  ];

  for (const layout of layouts) {
    for (const base of bases) {
      let dir = base;
      for (let depth = 0; depth < 40; depth++) {
        const candidate = path.join(dir, layout);
        if (fs.existsSync(candidate)) {
          return candidate;
        }
        const parent = path.dirname(dir);
        if (parent === dir) {
          break;
        }
        dir = parent;
      }
    }
  }

  throw new Error("Unable to locate the node-jsonfile module");
}

describe("jsonfile when graceful-fs cannot be loaded", () => {
  it("falls back to the core fs module to read and parse a JSON file", () => {
    const modulePath = locateJsonfileModule();

    let jsonfile: { readFileSync: (file: string) => any } | undefined;
    jest.isolateModules(() => {
      jsonfile = require(modulePath);
    });

    const directory = fs.mkdtempSync(path.join(os.tmpdir(), "jsonfile-fallback-"));
    try {
      const file = path.join(directory, "data.json");
      const contents = { name: "jsonfile", values: [1, 2, 3] };
      fs.writeFileSync(file, JSON.stringify(contents), "utf8");

      expect(jsonfile!.readFileSync(file)).toEqual(contents);
    } finally {
      fs.rmSync(directory, { recursive: true, force: true });
    }
  });
});
